<style>
.cs-shell{max-width:1100px}.cs-card{background:var(--bs-body-bg,#fff);border:1px solid var(--bs-border-color,#dce2e8);border-radius:18px;padding:1.5rem;box-shadow:0 10px 35px rgba(15,23,42,.08)}.question-block{padding:1rem;border-radius:14px;background:rgba(100,116,139,.07)}.choice-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:.65rem}.choice input,.score-row input,.yes-no input{position:absolute;opacity:0}.choice span,.score-row span,.yes-no span{display:block;border:1px solid var(--bs-border-color);border-radius:10px;padding:.75rem;text-align:center;cursor:pointer}.choice input:checked+span,.score-row input:checked+span,.yes-no input:checked+span{background:#2563eb;color:#fff;border-color:#60a5fa;box-shadow:0 0 0 3px rgba(37,99,235,.2)}.score-row,.yes-no{display:flex;gap:.6rem;flex-wrap:wrap}.score-row label{flex:1;min-width:48px}.yes-no label{min-width:90px}.buyer-section,.non-buyer-section{display:none}[data-status=purchased] .buyer-section,[data-status=not_purchased] .non-buyer-section{display:block}[data-bs-theme=dark] .cs-card{background:#111827;border-color:#334155}[data-bs-theme=dark] .question-block{background:rgba(148,163,184,.09)}@media(max-width:576px){.cs-card{padding:1rem}.choice-grid{grid-template-columns:1fr 1fr}}
</style>
